		/** 
		 * Tests creating a new Exposure.
		 */
		public void testCreate() throws Throwable {
			LOGGER.info( "\n======== CREATE ======== ");
			LOGGER.info( "-- Attempting to create a Exposure");

			StringBuilder msg = new StringBuilder( "-- Failed to create a Exposure" );

			try {            
				Exposure entity = ExposureService.getExposureInstance().createExposure( generateNewEntity() );
				thePrimaryKey = entity.getExposureId();
				LOGGER.info( "-- Successfully created a Exposure with primary key" + thePrimaryKey );
			}
			catch (Exception e) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : " + e );

				throw e;
			}
		}

		/** 
		 * Tests reading a Exposure. 
		 */
		public Exposure testRead() throws Throwable {
			LOGGER.info( "\n======== READ ======== ");
			LOGGER.info( "-- Reading a previously created Exposure" );

			Exposure entity = null;
			StringBuilder msg = new StringBuilder( "-- Failed to read Exposure with primary key" );
			msg.append( thePrimaryKey );
			
			ExposureFetchOneSummary fetchOneSummary = new ExposureFetchOneSummary( thePrimaryKey );

			try {
				entity = ExposureService.getExposureInstance().getExposure( fetchOneSummary );

				assertNotNull( entity,msg.toString() );

				LOGGER.info( "-- Successfully found Exposure " + entity.toString() );
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : " + e );

				throw e;
			}
			
			return entity;
		}

		/** 
		 * Tests updating a Exposure.
		 */
		public void testUpdate() throws Throwable {
			LOGGER.info( "\n======== UPDATE ======== ");
			LOGGER.info( "-- Attempting to update a Exposure." );

			StringBuilder msg = new StringBuilder( "Failed to update a Exposure : " );        
			Exposure entity = null;

			try {            
				entity = testRead();

				assertNotNull( entity, msg.toString() );

				LOGGER.info( "-- Now updating the created Exposure." );

				// for use later on...
				thePrimaryKey = entity.getExposureId();

				ExposureService proxy = ExposureService.getExposureInstance();            
				proxy.updateExposure( entity );   

				LOGGER.info( "-- Successfully saved Exposure - " + entity.toString() );
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : primarykey = " + thePrimaryKey + " : entity-" +  entity + " : " + e );

				throw e;
			}
		}

		/** 
		 * Tests deleting a Exposure.
		 */
		public void testDelete() throws Throwable {
			LOGGER.info( "\n======== DELETE ======== ");
			LOGGER.info( "-- Deleting a previously created Exposure." );

			try{
			    Exposure entity = testRead(); 
				ExposureService.getExposureInstance().delete( entity );

				LOGGER.info( "-- Successfully deleted Exposure with primary key " + thePrimaryKey );            
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( "-- Failed to delete Exposure with primary key " + thePrimaryKey );

				throw e;
			}
		}

		/**
		 * Tests getting all Exposures.
		 */
		public void testGetAll() throws Throwable {    
			LOGGER.info( "======== GETALL ======== ");
			LOGGER.info( "-- Retrieving Collection of Exposures:" );

			StringBuilder msg = new StringBuilder( "-- Failed to get all Exposure : " );        
			List<Exposure> collection  = null;

			try {
				// call the static get method on the ExposureService
				collection = ExposureService.getExposureInstance().getAllExposure();

				if ( collection == null || collection.size() == 0 ) {
					LOGGER.warning( unexpectedErrorMsg );
					LOGGER.warning( msg.toString() + " Empty collection returned."  );
				}
				else {
					// Now print out the values
					Exposure entity = null;            
					Iterator<Exposure> iter = collection.iterator();
					int index = 1;

					while( iter.hasNext() ) {
						// Retrieve the entity   
						entity = iter.next();

						assertNotNull( entity,"-- null entity in Collection." );
						assertNotNull( entity.getExposureId(), "-- entity in Collection has a null primary key" );        

						LOGGER.info( " - " + String.valueOf(index) + ". " + entity.toString() );
						index++;
					}
				}
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : " + e );

				throw e;
			}
		}

